// @ts-ignore
import { VERSIONCHECK } from 'global';

import { version as currentVersion } from '../version';

import { Module, API } from '../index';

export interface Version {
  version: string;
  info?: { plain: string };
  [key: string]: any;
}

export interface UnknownEntries {
  [key: string]: {
    [key: string]: any;
  };
}

export interface Versions {
  latest?: Version;
  next?: Version;
  current?: Version;
}

export interface SubState {
  versions: Versions & UnknownEntries;
  lastVersionCheck: number;
  dismissedVersionNotification: undefined | string;
}

export interface SubAPI {
  getCurrentVersion: () => Version;
  getLatestVersion: () => Version;
  versionUpdateAvailable: () => boolean;
}

// The `VERSIONCHECK` global is injected into the bundle at server startup, so the
// version data is available synchronously to the client — no runtime HTTP request.
const getVersionCheckData = (): Versions => {
  try {
    return { ...(JSON.parse(VERSIONCHECK || '{}').data || {}) };
  } catch (e) {
    return {};
  }
};

export default function({ store, mode }: Module) {
  const { versions: persistedVersions = {}, dismissedVersionNotification } = store.getState();

  // Check to see if we have info about the current version persisted
  const persistedCurrentVersion = Object.values(persistedVersions).find(
    (v: Version) => v.version === currentVersion
  ) as Version;

  const { latest, next } = getVersionCheckData();

  const state = {
    versions: {
      ...persistedVersions,
      latest,
      next,
      current: {
        version: currentVersion,
        ...(persistedCurrentVersion && { info: persistedCurrentVersion.info }),
      },
    },
    dismissedVersionNotification,
  };

  const api: SubAPI = {
    getCurrentVersion: () => {
      const {
        versions: { current },
      } = store.getState();
      return current;
    },
    getLatestVersion: () => {
      const {
        versions: { latest: latestVersion },
      } = store.getState();
      return latestVersion;
    },
    versionUpdateAvailable: () => {
      const latestVersion = api.getLatestVersion();
      const current = api.getCurrentVersion();

      // No known latest version: nothing to update to.
      if (!latestVersion || !latestVersion.version) {
        return false;
      }

      // We never notify about prerelease versions being available.
      if (semver.prerelease(latestVersion.version)) {
        return false;
      }

      // Strip any prerelease suffix from the current version so that e.g. a
      // prerelease of `3.1.0` is compared against the latest stable as `3.1.0`.
      const currentStable = `${semver.major(current.version)}.${semver.minor(
        current.version
      )}.${semver.patch(current.version)}`;

      // Same version (or the current one is newer): no update.
      if (semver.gte(currentStable, latestVersion.version)) {
        return false;
      }

      // Only minor/major bumps are worth notifying about, not patches.
      const diff = semver.diff(currentStable, latestVersion.version);
      return diff === 'minor' || diff === 'major';
    },
  };

  // The version data is already in state (injected at build time), so there is no
  // async fetching or permanent persistence to do here.
  const init = async ({ api: fullApi }: API) => {
    if (api.versionUpdateAvailable()) {
      const latestVersion = api.getLatestVersion();
      const { dismissedVersionNotification: dismissed } = store.getState();

      if (latestVersion.version !== dismissed && mode !== 'production') {
        fullApi.addNotification({
          id: 'update',
          link: '/settings/about',
          content: `🎉 Storybook ${latestVersion.version} is available!`,
          onClear() {
            store.setState(
              { dismissedVersionNotification: latestVersion.version },
              { persistence: 'permanent' }
            );
          },
        });
      }
    }
  };

  return { init, state, api };
}
